        ["احراز هویت OpenVPN رد شد. نام کاربری و رمز را با همان حساب OpenVPN GUI یکسان کنید؛ بعضی سرورها بعد از قطع ناگهانی یک‌بار دیگر رد می‌کنند."] = "Аутентификация OpenVPN отклонена. Укажите то же имя и пароль, что в OpenVPN GUI; некоторые серверы один раз отклоняют повторное подключение после обрыва.",
        ["احراز هویت OpenVPN رد شد. نام کاربری و رمز را با همان حساب OpenVPN GUI یکسان کنید؛ اگر تازه قطع شده ۳۰–۶۰ ثانیه صبر کنید و فقط یک دستگاه وصل باشد."] = "Аутентификация OpenVPN отклонена. Укажите те же данные, что в OpenVPN GUI; если только что отключились, подождите 30–60 секунд и оставьте подключённым одно устройство.",
        ["اگر بعد از آن AUTH_FAILED دیدید، ۳۰–۶۰ ثانیه صبر کنید و دوباره Connect بزنید."] = "Если после этого появится AUTH_FAILED, подождите 30–60 секунд и подключитесь снова.",
        ["لطفاً دوباره متصل شوید."] = "Подключитесь снова.",
        ["TLS OpenVPN کامل نشد. ریموت‌های فایل .ovpn، فیلترینگ شبکه یا نسخه OpenVPN Community را بررسی کنید؛ TunnelX حالت DCO را غیرفعال کرده است."] = "TLS OpenVPN не завершился. Проверьте remote в файле .ovpn, фильтрацию сети или версию OpenVPN Community; TunnelX отключает режим DCO.",
        ["هیچ سرور remote قابل استفاده در فایل .ovpn باقی نمانده است. آدرس سرور، DNS یا نصب OpenVPN Community را بررسی کنید."] = "В файле .ovpn не осталось пригодного remote-сервера. Проверьте адрес сервера, DNS или установку OpenVPN Community.",
        ["آداپتر OpenVPN آماده است"] = "Адаптер OpenVPN готов",
        ["OpenVPN متصل شد (Split Tunnel)"] = "OpenVPN подключён (Split Tunnel)",
        ["در حال قطع اتصال OpenVPN..."] = "Отключение OpenVPN...",
        ["  •  📊 تونل "] = "  •  📊 Туннель ",
        ["برای سرورهای SOCKS5 یا HTTP Proxy، اطلاعات سرور را جداگانه وارد کنید."] = "Для серверов SOCKS5 или HTTP Proxy укажите данные сервера отдельно.",
        ["TunnelX فایل .ovpn را با OpenVPN Community اجرا می‌کند و مسیر/DNS پیش‌فرض OpenVPN را کنترل می‌کند تا فقط برنامه‌های انتخابی از تونل عبور کنند."] = "TunnelX запускает файл .ovpn через OpenVPN Community и управляет маршрутом и DNS OpenVPN по умолчанию, чтобы через туннель шли только выбранные приложения.",
        ["OpenVPN Connect به‌تنهایی کافی نیست؛ اگر Community نصب نباشد، از دکمه دانلود پایین استفاده کنید."] = "Одного OpenVPN Connect недостаточно; если Community не установлен, воспользуйтесь кнопкой загрузки ниже.",
        ["انتخاب برنامه"] = "Выбрать приложение",
        ["لایسنس: {0}"] = "Лицензия: {0}",
        ["برای اتصال VPN ویندوز. آدرس سرور، نام کاربری، رمز عبور و Pre-Shared Key لازم است. اگر وصل نشد، PSK، فایروال و تنظیمات VPN ویندوز را بررسی کنید."] = "Для VPN-подключения Windows. Нужны адрес сервера, имя пользователя, пароль и Pre-Shared Key. Если не подключается, проверьте PSK, брандмауэр и параметры VPN в Windows.",
        ["لینک یا JSON کانفیگ را وارد کنید یا از کلیپ‌بورد پیست کنید. TunnelX معمولاً sing-box را اجرا می‌کند و برای قابلیت‌هایی مثل xhttp از Xray-core استفاده می‌کند."] = "Введите ссылку или JSON конфига либо вставьте их из буфера обмена. Обычно TunnelX запускает sing-box, а для возможностей вроде xhttp использует Xray-core.",
        ["برای پراکسی خارجی آماده. نوع پراکسی، آدرس، پورت و در صورت نیاز نام کاربری/رمز را وارد کنید. این با پراکسی داخلی 127.0.0.1 فرق دارد."] = "Для готового внешнего прокси. Укажите протокол, адрес, порт и при необходимости учётные данные. Это не внутренний прокси 127.0.0.1.",
        ["فایل ovpn را انتخاب کنید. OpenVPN Community باید جداگانه نصب باشد؛ OpenVPN Connect برای Split Tunneling مناسب نیست. اگر سرور رمز می‌خواهد، نام کاربری و رمز را در TunnelX وارد کنید."] = "Выберите файл ovpn. OpenVPN Community нужно установить отдельно; OpenVPN Connect для раздельного туннелирования не подходит. Если сервер просит вход, укажите данные в TunnelX.",
        ["از لیست برنامه‌های پیدا شده انتخاب کنید یا فایل exe را دستی اضافه کنید. برای Store/MSIX/WebView2 برنامه را باز نگه دارید و بروزرسانی لیست را بزنید."] = "Выберите программу из найденных или вручную добавьте файл exe. Для приложений Store/MSIX/WebView2 держите программу открытой и обновите список.",
        ["«مستقیم بماند» یعنی مقصد از تونل عبور نکند. «از تونل عبور کند» یعنی مقصد حتی بدون انتخاب برنامه وارد تونل شود. دامنه‌ها زیردامنه‌ها را هم پوشش می‌دهند."] = "«Оставить напрямую» — назначение обходит туннель. «Через туннель» — назначение идёт в туннель даже без выбора приложения. Домены охватывают и поддомены.",
        ["پورت پراکسی محلی، MTU خودکار، DNS Optimization، Game Mode، اعلان‌های وضعیت، اجرای خودکار ویندوز و اتصال خودکار اینجاست."] = "Здесь локальный порт прокси, автоматический MTU, DNS Optimization, Game Mode, уведомления, автозапуск Windows и автоподключение.",
        ["مدت اتصال، IP، مصرف تونل، مصرف خارج تونل، سلامت Split Tunnel، مصرف برنامه‌ها و تاریخچه اتصال‌ها را نشان می‌دهد."] = "Показывает длительность, IP, расход туннеля, расход вне туннеля, состояние раздельного туннеля, расход приложений и историю подключений.",
        ["جزئیات و لاگ‌ها"] = "Подробности и логи",
        ["از دکمه جزئیات، لاگ‌ها را با فیلتر خطا، هشدار، DNS یا Route ببینید. قبل از ارسال عمومی لاگ، رمزها، کلیدها، UUID و endpoint خصوصی را حذف کنید."] = "Кнопка «Подробности» показывает логи с фильтром по ошибкам, предупреждениям, DNS или маршрутам. Перед тем как делиться логами, удалите пароли, ключи, UUID и частные endpoint.",
        ["اتصال برقرار نمی‌شود"] = "Подключение не начинается",
        ["برنامه را با Administrator اجرا کنید. فایروال، آنتی‌ویروس، آدرس سرور، پورت، رمزها، PSK، نصب OpenVPN Community و اعتبار کانفیگ را بررسی کنید."] = "Запустите программу от имени администратора. Проверьте брандмауэр, антивирус, адрес сервера, порт, учётные данные, PSK, установку OpenVPN Community и сам конфиг.",
        ["ترافیک برنامه از تونل عبور نمی‌کند"] = "Трафик программы не идёт через туннель",
        ["برنامه را در تب برنامه‌ها فعال کنید. اگر چندپردازشی است، برنامه را باز نگه دارید و لیست برنامه‌ها را دوباره بارگذاری کنید."] = "Включите программу на вкладке «Приложения». Если у неё несколько процессов, держите её открытой и обновите список приложений.",
        ["پراکسی کار نمی‌کند"] = "Прокси не работает",
        ["برای پروفایل پراکسی، آدرس، پورت، نوع و اطلاعات ورود را بررسی کنید. برای ابزارهای محلی، آدرس 127.0.0.1 و پورت تنظیمات را وارد کنید."] = "Для профиля прокси проверьте адрес, порт, тип и данные входа. Для локальных инструментов укажите 127.0.0.1 и порт из настроек.",
        ["DNS، IPv6 یا Leak غیرعادی است"] = "DNS, IPv6 или утечка выглядят необычно",
        ["یک بار قطع و وصل کنید تا مسیرها و قوانین DNS دوباره ساخته شوند. اگر مشکل ماند، لاگ‌های DNS و Route را بررسی کنید."] = "Один раз отключитесь и подключитесь снова, чтобы маршруты и правила DNS собрались заново. Если проблема останется, посмотрите логи DNS и маршрутов.",
